// The world's own lists, repeated here so that this file stands alone. A test holds them equal.
const KINDS                         = ['frontage', 'works', 'reservoir', 'observatory', 'utility'];
const STAGES                          = ['concept', 'planned', 'designed', 'building', 'working', 'mature'];
export const DEFINITION_KINDS = KINDS;
export const DEFINITION_STAGES = STAGES;

/** Where the file lives in a repository. */
export const DEFINITION_FILE = 'patrick-world.json';
export const DEFINITION_VERSION = 1;

/**
 * How a city may say it is connected. The world's own kinds, and one more: `fed-by` is
 * `feeds` seen from the other end, so that a city can say what it receives as well as what
 * it sends without waiting for the other city to say it.
 */
                                                   
const LINK_KINDS                              = ['related', 'shares', 'feeds', 'fed-by', 'split-from'];

                                  
     
                                                                                        
                                                                  
     
             
               
                                            
                    
                                                                        
                      
     
                                                                                           
                                                                
     
                   
                                                                                 
                
                                            
                     
                
 

                               
                                               
             
                                                                                          
                         
                                                        
                   
 

                                 
                                     
     
                                                                                           
                                              
     
             
               
                                                                    
               
                                                                       
                  
     
                                                                                          
                                                                                        
                                                                                      
     
                              
                         
 

                                                                                                          

// ───────────────────────── Reading the file ─────────────────────────

const HANDLE = /^[a-z0-9]+(-[a-z0-9]+)*$/;

const isRecord = (v         )                               => typeof v === 'object' && v !== null && !Array.isArray(v);
const isText = (v         )              => typeof v === 'string' && v.trim() !== '';
const isHandle = (v         )              => typeof v === 'string' && HANDLE.test(v);

/** A path a repository could hold: relative, forward slashes, never climbing out. */
function cleanPath(v         )                {
  if (typeof v !== 'string') return null;
  const path = v.trim().replace(/^\.\//, '').replace(/\/+$/, '');
  if (path === '' || path.startsWith('/') || path.includes('\\') || path.split('/').includes('..')) return null;
  return path;
}

function optionalTextList(v         , what        , errors          )                       {
  if (v === undefined) return undefined;
  if (!Array.isArray(v) || !v.every(isText)) {
    errors.push(`${what} must be a list of words.`);
    return undefined;
  }
  return v.map((s) => s.trim());
}

function readFeature(v         , n        , seen             , errors          )                         {
  const label = `Feature ${n}`;
  if (!isRecord(v)) {
    errors.push(`${label} is not an object.`);
    return null;
  }
  const before = errors.length;
  const called = isHandle(v.id) ? `Feature "${v.id}"` : label;

  if (!isHandle(v.id)) errors.push(`${label} needs an id in lower-case words joined by hyphens.`);
  else if (seen.has(v.id)) errors.push(`Two features share the id "${v.id}".`);
  else seen.add(v.id);

  if (!isText(v.name)) errors.push(`${called} has no name.`);
  if (!(KINDS                      ).includes(v.kind)) errors.push(`${called} needs a kind: one of ${KINDS.join(', ')}.`);
  if (!(STAGES                      ).includes(v.stage)) errors.push(`${called} needs a stage: one of ${STAGES.join(', ')}.`);

  let paths                      ;
  if (v.paths !== undefined) {
    if (!Array.isArray(v.paths)) errors.push(`${called}: paths must be a list.`);
    else {
      paths = [];
      for (const raw of v.paths) {
        const path = cleanPath(raw);
        if (path === null) errors.push(`${called}: "${String(raw)}" is not a path inside the repository.`);
        else if (!paths.includes(path)) paths.push(path);
      }
    }
  }
  const methods = optionalTextList(v.methods, `${called}: methods`, errors);
  if (v.ward !== undefined && !isText(v.ward)) errors.push(`${called}: ward must be a name.`);
  if (v.note !== undefined && !isText(v.note)) errors.push(`${called}: note must be a sentence.`);
  if (errors.length > before) return null;

  const feature                  = {
    id: v.id          ,
    name: (v.name          ).trim(),
    kind: v.kind               ,
    stage: v.stage                ,
  };
  if (paths !== undefined && paths.length > 0) feature.paths = paths;
  if (methods !== undefined && methods.length > 0) feature.methods = methods;
  if (isText(v.ward)) feature.ward = v.ward.trim();
  if (isText(v.note)) feature.note = v.note.trim();
  return feature;
}

function readLink(v         , n        , self         , errors          )                      {
  const label = `Link ${n}`;
  if (!isRecord(v)) {
    errors.push(`${label} is not an object.`);
    return null;
  }
  const before = errors.length;
  if (!isHandle(v.to)) errors.push(`${label} needs "to": the id of another city.`);
  else if (v.to === self) errors.push(`${label} points at this city itself.`);
  if (!(LINK_KINDS                      ).includes(v.kind)) errors.push(`${label} needs a kind: one of ${LINK_KINDS.join(', ')}.`);
  if (v.carries !== undefined && !isText(v.carries)) errors.push(`${label}: carries must say what flows.`);
  if (errors.length > before) return null;

  const link               = { to: v.to          , kind: v.kind                     };
  if (isText(v.carries)) link.carries = v.carries.trim();
  return link;
}

/**
 * Read a definition file. Every problem is reported at once, in plain words, so the file
 * can be fixed in one pass. A file with any problem is refused whole: half a definition
 * would draw a city its owner did not describe. Keys this version does not know are ignored.
 */
export function parseDefinition(text        )                   {
  let value         ;
  try {
    value = JSON.parse(text);
  } catch (e) {
    return { ok: false, errors: [`Not valid JSON: ${e instanceof Error ? e.message : String(e)}`] };
  }
  if (!isRecord(value)) return { ok: false, errors: ['The file must hold one object.'] };

  const errors           = [];
  if (value.version !== DEFINITION_VERSION) errors.push(`"version" must be ${DEFINITION_VERSION}.`);
  if (!isHandle(value.id)) errors.push('The city needs an id in lower-case words joined by hyphens.');
  if (!isText(value.name)) errors.push('The city has no name.');
  if (!isText(value.what)) errors.push('"what" must say what the city is.');
  if (value.region !== undefined && !isHandle(value.region)) errors.push('"region" must be a region id.');

  const features                    = [];
  if (!Array.isArray(value.features)) errors.push('"features" must be a list, even an empty one.');
  else {
    const seen = new Set        ();
    value.features.forEach((f, i) => {
      const feature = readFeature(f, i + 1, seen, errors);
      if (feature !== null) features.push(feature);
    });
  }

  const links                 = [];
  if (value.links !== undefined) {
    if (!Array.isArray(value.links)) errors.push('"links" must be a list.');
    else {
      value.links.forEach((l, i) => {
        const link = readLink(l, i + 1, value.id, errors);
        if (link !== null) links.push(link);
      });
    }
  }

  if (errors.length > 0) return { ok: false, errors };

  const definition                 = {
    version: DEFINITION_VERSION,
    id: value.id          ,
    name: (value.name          ).trim(),
    what: (value.what          ).trim(),
    features,
  };
  if (isHandle(value.region)) definition.region = value.region;
  if (links.length > 0) definition.links = links;
  return { ok: true, definition };
}

// ───────────────────────── The owner's word against the evidence ─────────────────────────

/** The furthest stage a feature's commits evidence, by the rules in the GitHub transform. */
                                                               

/**
 * The stage the map draws for a declared feature.
 *
 * `declared` is what the file says. `evidenced` is the furthest stage the commits on the
 * feature's paths support, or null when there are no commits on them at all.
 *
 * The rule: FACT BEATS CLAIM, AND CLAIM BEATS INFERENCE.
 *
 *   - That work happened is a fact: commits exist. So a feature the file still calls an
 *     idea or a plan, with commits on its paths, is drawn as building. The file is stale.
 *   - That the work amounts to `working` or `mature` is only ever an inference from the
 *     rhythm of commits (three quiet weeks reads the same for finished and for abandoned).
 *     There the owner's word wins in both directions: it can hold a feature at `building`
 *     that the commits would call working, and it can call working what they would not.
 */
export function settleStage(declared              , evidenced                       )               {
  const started = STAGES.indexOf('building');
  if (evidenced !== null && STAGES.indexOf(declared) < started) return 'building';
  return declared;
}
